let vector = [];
const TOTAL_DIM = 299; //originally 300 but remove index 234
let centerX, centerY;
const maxRadius = 350;
const minRadius = 10;
let displayWord = "";

let myFont;
function preload() {
  myFont = loadFont('couriernew.ttf');
}

function setup() {
  createCanvas(800,850);
  centerX = width / 2;
  centerY = (height / 2) + 40;
  randomIndex = Math.floor(Math.random() * data.length);
  // Simulated LLM vector data
  // for (let i = 0; i < TOTAL_DIM; i++) {
  //   // Using noise to simulate related "clumps" of dimensions
  //   vector[i] = noise(i * 0.05); 
  // }
  vector = data[randomIndex];
  displayWord = vector.shift();
  let vmin = Math.min.apply(null, vector);
  vector.splice(vector.indexOf(vmin), 1);
  console.log(displayWord);
  textFont(myFont);
  textSize(40);
  textAlign(CENTER, CENTER);
  noLoop();
}

function draw() {
  background("#dfded8ff");
  
  push();
  translate(centerX, centerY);
  
  // 1. Draw the Star Glyph Shape
  beginShape();
  noFill();
  strokeWeight(1);
  
  for (let i = 0; i < TOTAL_DIM; i++) {
    let angle = map(i, 0, TOTAL_DIM, 0, TWO_PI);
    
    // Calculate radius based on vector value
    // We add a small base radius so the shape doesn't collapse to 0
    
    let r = map(vector[i], -1.5, 1.4, minRadius, maxRadius);
    
    let x = r * cos(angle);
    let y = r * sin(angle);
    
    stroke(0);
    
    vertex(x, y);
  }
  endShape(CLOSE);
  
  // 2. Optional: Draw a subtle "Web" or Grid
  stroke(0, 50);
  noFill();
  ellipse(0, 0, maxRadius * 2);
  ellipse(0, 0, maxRadius + (minRadius / 2)); //0 base line

  fill(0);
  text(displayWord, 0, -400);
  
  pop();
}


